//! 🧫️ Actual generic operation cursors move original typed fields through one-item native loans.
use super::*;
use protocol::{OpBinary,OpBinaryReceiving,OpBinaryReceivingCursor};
use semio_framework_value::retirement::controlled::ControlledRetirement;
#[derive(Clone,Debug,PartialEq,semio_framework_dsl_record_derive::DslEnum,semio_framework_dsl_record_derive::DslReceiving,semio_framework_value::RetireOwned)]
enum OriginalMutation{Rename{text:String,items:Vec<String>}}
impl OpBinary for OriginalMutation{
 fn encode_op(&self)->Result<Vec<u8>,protocol::ProtocolError>{crate::os_dsl::variants_binary::encode_op(self)}
 fn decode_op(bytes:&[u8])->Result<Self,protocol::ProtocolError>{crate::os_dsl::variants_binary::decode_op(bytes)}
}
crate::original_ordinal_operation_receiving!(OriginalMutation);
#[test]
fn original_command_receiving_operation_original_record_and_owned_fields_resume_one_item(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let expected=OriginalMutation::Rename{text:serde_json::from_value(fixture["text"].clone()).unwrap(),items:serde_json::from_value(fixture["items"].clone()).unwrap()};let encoded=expected.encode_op().unwrap();let mut source:Vec<u8>=serde_json::from_value(fixture["source"]["prefix"].clone()).unwrap();let start=source.len();source.extend_from_slice(&encoded);let end=source.len();source.extend(serde_json::from_value::<Vec<u8>>(fixture["source"]["suffix"].clone()).unwrap());let f=&fixture["turn"];let grant=RetainedCloneGrant{maximum_items:f["items"].as_u64().unwrap()as usize,maximum_copy_bytes:f["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:f["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:f["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:f["depth"].as_u64().unwrap()as usize};
 let mut callback=|_|true;let mut native=NativeDecodeControl::new(1<<24,&mut callback);let(mut cursor,admitted)=OriginalMutation::admit_receiving(&source,(start,end),grant).unwrap().unwrap();assert_eq!(admitted.copied_items,1);let wrong=source.clone();assert!(cursor.demands(&wrong,grant.maximum_copy_bytes).is_err());let mut turns=0;let mut original_text=None;
 while !cursor.is_ready(){assert!(turns<10000);if cursor.phase==5&&original_text.is_none(){if let Some(FieldValue::Record(record))=cursor.generic.value.as_ref(){if let Some(FieldValue::Text(text))=record.get(0){original_text=Some(text.as_ptr()as usize);}}}let progress=cursor.step(&source,&mut native,grant).unwrap();assert_eq!(progress.copied_items,1);assert!(progress.fits(grant));turns+=1;}
 let mut output=None;assert_eq!(cursor.take_into(&mut output,grant).unwrap().copied_items,1);assert_eq!(output.as_ref(),Some(&expected));let OriginalMutation::Rename{text,..}=output.as_ref().unwrap();assert_eq!(original_text,Some(text.as_ptr()as usize));
 while !cursor.terminal_is_empty(){let demand=cursor.close_demands(grant.maximum_copy_bytes).unwrap();native.charge(demand.capacity_bytes).unwrap();cursor.close_step(grant).unwrap();}let mut output=ControlledRetirement::new(output.take().unwrap()).ok().unwrap();while !output.terminal_is_empty(){output.step(grant).unwrap();}println!("[DEBUG] Original operation receiving originalFullSource=true oneItemContinuation=true originalNative=true originalTypedTextMoved=true independentSerdeOutput=true paidTerminalClose=true turns={turns}");
}

#[derive(Clone,Debug,PartialEq,semio_framework_dsl_record_derive::DslEnum,semio_framework_dsl_record_derive::DslReceiving,semio_framework_value::RetireOwned)]
enum OriginalTaggedMutation{Remove{},Rename{text:String}}
const ORIGINAL_PROTOCOL:&str=include_str!("🧫️fixtures/🏷️protocol.semio");
impl OpBinary for OriginalTaggedMutation{fn encode_op(&self)->Result<Vec<u8>,protocol::ProtocolError>{crate::os_dsl::variants_binary::encode_tagged_op(ORIGINAL_PROTOCOL,self)}fn decode_op(bytes:&[u8])->Result<Self,protocol::ProtocolError>{crate::os_dsl::variants_binary::decode_tagged_op(ORIGINAL_PROTOCOL,bytes)}}
crate::original_tagged_operation_receiving!(OriginalTaggedMutation,ORIGINAL_PROTOCOL);
#[test]
fn original_command_receiving_operation_authored_tagged_header_resumes_each_original_item(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🏷️tagged.json")).unwrap();let expected=OriginalTaggedMutation::Rename{text:fixture["text"].as_str().unwrap().into()};let source=expected.encode_op().unwrap();let tag=fixture["tag"].as_u64().unwrap();assert_eq!(&source[..3],&[1,(tag as u8&127)|128,(tag>>7)as u8]);let f=&fixture["turn"];let grant=RetainedCloneGrant{maximum_items:f["items"].as_u64().unwrap()as usize,maximum_copy_bytes:f["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:f["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:f["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:f["depth"].as_u64().unwrap()as usize};let mut callback=|_|true;let mut native=NativeDecodeControl::new(1<<24,&mut callback);let(mut cursor,_)=OriginalTaggedMutation::admit_receiving(&source,(0,source.len()),grant).unwrap().unwrap();let mut turns=0;let mut selections=0;while !cursor.is_ready(){assert!(turns<10000);if cursor.phase==2{selections+=1;}let mut denied=grant;denied.maximum_items=0;assert_eq!(cursor.step(&source,&mut native,denied).unwrap(),Default::default());let progress=cursor.step(&source,&mut native,grant).unwrap();assert_eq!(progress.copied_items,1);assert!(progress.fits(grant));turns+=1;}assert_eq!(selections,2);let mut output=None;cursor.take_into(&mut output,grant).unwrap();assert_eq!(output.as_ref(),Some(&expected));while !cursor.terminal_is_empty(){let demand=cursor.close_demands(grant.maximum_copy_bytes).unwrap();native.charge(demand.capacity_bytes).unwrap();cursor.close_step(grant).unwrap();}let mut output=ControlledRetirement::new(output.take().unwrap()).ok().unwrap();while !output.terminal_is_empty(){output.step(grant).unwrap();}println!("[DEBUG] Original operation receiving authoredConstTags=true boundedTagSelection=true originalOneItem=true independentSerdeOutput=true paidClose=true turns={turns}");
}
